from pathlib import Path
from reportlab.lib import colors
from reportlab.lib.enums import TA_CENTER
from reportlab.lib.pagesizes import A4
from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
from reportlab.lib.units import mm
from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, Table, TableStyle, PageBreak, Image

ROOT = Path(__file__).resolve().parents[1]
OUT = ROOT / "output/pdf/ROOSE_Hotel_Reservation_System_Project_Report.pdf"
OUT.parent.mkdir(parents=True, exist_ok=True)
GOLD = colors.HexColor('#B88A3B'); BROWN = colors.HexColor('#4C2D18')
PALE = colors.HexColor('#F6F0E5'); INK = colors.HexColor('#302820')
W, H = A4
s = getSampleStyleSheet()
s.add(ParagraphStyle(name='TitleR', parent=s['Title'], fontName='Times-Bold', fontSize=29, leading=34, textColor=BROWN, alignment=TA_CENTER))
s.add(ParagraphStyle(name='SubR', parent=s['Normal'], fontName='Times-Italic', fontSize=14, leading=20, textColor=GOLD, alignment=TA_CENTER))
s.add(ParagraphStyle(name='H1R', parent=s['Heading1'], fontName='Times-Bold', fontSize=18, leading=22, textColor=BROWN, spaceAfter=8))
s.add(ParagraphStyle(name='H2R', parent=s['Heading2'], fontName='Times-Bold', fontSize=12, leading=15, textColor=BROWN, spaceBefore=7, spaceAfter=4))
s.add(ParagraphStyle(name='BodyR', parent=s['BodyText'], fontName='Helvetica', fontSize=9, leading=13, textColor=INK, spaceAfter=6))
s.add(ParagraphStyle(name='CellR', parent=s['BodyText'], fontName='Helvetica', fontSize=7.4, leading=9, textColor=INK))
s.add(ParagraphStyle(name='HeadR', parent=s['BodyText'], fontName='Helvetica-Bold', fontSize=7.4, leading=9, textColor=colors.white))
s.add(ParagraphStyle(name='NoteR', parent=s['BodyText'], fontName='Helvetica-Bold', fontSize=9, leading=13, textColor=BROWN, backColor=PALE, borderColor=GOLD, borderWidth=.6, borderPadding=8, spaceBefore=5, spaceAfter=8))

def p(txt, style='BodyR'): return Paragraph(txt, s[style])
def table(rows, widths):
    data=[[p(str(v), 'HeadR' if i==0 else 'CellR') for v in row] for i,row in enumerate(rows)]
    t=Table(data,colWidths=widths,repeatRows=1,hAlign='LEFT')
    t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),BROWN),('GRID',(0,0),(-1,-1),.35,GOLD),('VALIGN',(0,0),(-1,-1),'TOP'),('ROWBACKGROUNDS',(0,1),(-1,-1),[colors.white,PALE]),('LEFTPADDING',(0,0),(-1,-1),5),('RIGHTPADDING',(0,0),(-1,-1),5),('TOPPADDING',(0,0),(-1,-1),4),('BOTTOMPADDING',(0,0),(-1,-1),4)]))
    return t
def frame(c, doc):
    c.saveState()
    if doc.page>1:
        c.setStrokeColor(GOLD); c.line(18*mm,H-15*mm,W-18*mm,H-15*mm)
        c.setFillColor(BROWN); c.setFont('Times-Bold',9); c.drawString(18*mm,H-12.5*mm,'ROOSE HOTEL  |  GROUP 10')
        c.setFillColor(colors.HexColor('#6D6257')); c.setFont('Helvetica',7.5); c.drawRightString(W-18*mm,12*mm,f'Project Report  •  {doc.page}')
    c.restoreState()

doc=SimpleDocTemplate(str(OUT),pagesize=A4,leftMargin=18*mm,rightMargin=18*mm,topMargin=21*mm,bottomMargin=21*mm,title='ROOSE Hotel Reservation System — Group 10 Project Report',author='Group 10')
st=[]
logo=ROOT/'assets/roose-brand-mark.png'
st += [Spacer(1,12*mm)]
if logo.exists(): st += [Image(str(logo),width=27*mm,height=27*mm,hAlign='CENTER'),Spacer(1,5*mm)]
st += [p('ROOSE HOTEL','TitleR'),p('Hotel Room Reservation System','SubR'),Spacer(1,8*mm)]
st += [table([['PROJECT 10 • GROUP 10','FINAL PROJECT REPORT'],['Incremental Development Model','28 November 2026']],[82*mm,82*mm]),Spacer(1,10*mm),p('Prepared by','H2R')]
st += [table([['Member','Role','Matriculation number'],['Ruth Ben-Osagie','C# Developer &amp; System Modeller','[ADD MATRIC NUMBER]'],['Julius-Imoisi Obehi','Project Manager &amp; Requirements Analyst','[ADD MATRIC NUMBER]'],['Evbuomwan Osasogie (Osaso)','QA Tester','[ADD MATRIC NUMBER]']],[52*mm,70*mm,42*mm]),Spacer(1,10*mm)]
st += [p('Luxury. Comfort. Excellence.','SubR'),Spacer(1,8*mm),p('Submission status: report prepared. Member numbers and a shareable demonstration link remain placeholders. A live group walkthrough and acceptance sign-off still need to be recorded.','NoteR'),PageBreak()]

st += [p('1. Project Overview','H1R'),p('ROOSE Hotel Reservation System is a Windows desktop application for authorized front-desk staff. It supports room and guest records, date-based room availability, reservations, accommodation charge summaries, and check-in/check-out. A local SQLite database stores project records.'),p('Objectives and scope','H2R'),table([['Objective','Delivered outcome'],['Manage hotel inventory','Seed and maintain 30 rooms, with category, capacity, rate, and operational status.'],['Support bookings','Register guests, search availability, create/update/cancel reservations.'],['Prevent conflicts','Validate dates and recheck room overlap at save time.'],['Complete a stay','Summarize accommodation charges and record arrival/departure timestamps.']],[43*mm,121*mm]),p('The first release is for one local Windows workstation. Public online booking, guest accounts, card payments, POS, housekeeping, payroll, multiple branches, and loyalty features are outside scope.'),p('Feasibility','H2R'),table([['Area','Assessment'],['Technical','Feasible for this course project using C# WinForms, .NET 9, SQLite, and layered code.'],['Operational','Labeled staff screens support front-desk tasks; protect the workstation and local database.'],['Schedule','The supplied 48-hour incremental plan was divided into six feature increments; release evidence is being finalized.']],[30*mm,134*mm]),p('Risk controls','H2R'),p('Double booking is controlled by rechecking conflicts before saving. Data mismatch is controlled by repository-owned schema and SQLite constraints. Integration risk is reduced by separating UI, Core rules, and Data access. Scope pressure is managed by deferring features outside the agreed reservation lifecycle.'),PageBreak()]

st += [p('2. Requirements Specification','H1R'),p('Primary user: receptionist or authorized staff. Hotel dates are local calendar dates. A stay occupies check-in through the night before check-out; check-out is an exclusive end date.'),table([['ID','Requirement','Acceptance condition'],['FR-01','Staff setup/login','Initial account; salted password hash; invalid credentials rejected.'],['FR-02','Dashboard','Room and daily operation summaries derived from records.'],['FR-03','Room records','Number, category, rate, capacity, operational status.'],['FR-04','Guest records','Create, search by name/phone/email, and update.'],['FR-05','Availability','Exclude maintenance rooms and active date overlaps.'],['FR-06','Create reservation','Save confirmed booking for registered guest and eligible room.'],['FR-07','Date/conflict rules','Check-out later than check-in; reject overlap.'],['FR-08','Manage reservation','Retrieve, modify, cancel; cancellation frees dates.'],['FR-09','Accommodation charge','Nightly rate × night count.'],['FR-10','Check-in/out','Eligible reservation only; update status and occupancy.'],['FR-11','Persistence','Records remain after restart.']],[17*mm,47*mm,100*mm]),p('Non-functional requirements','H2R'),p('Usability: clear forms and actions. Reliability and integrity: invalid data and conflicts are rejected without corrupting records. Persistence: local SQLite. Maintainability: presentation, business rules, and data access are separated. Compatibility: Windows desktop with the agreed .NET runtime.'),p('Key scenarios','H2R'),p('Staff searches a date range, selects an eligible room and registered guest, and confirms; the repository rechecks overlap before save. Adjacent stays are allowed. Cancelling frees dates. Eligible check-in records arrival and updates occupancy.'),PageBreak()]

st += [p('3. Design and Data Model','H1R'),p('Architecture','H2R'),table([['Layer','Responsibility'],['Windows Forms App','Screens, controls, and staff input.'],['Core','Entities, date/status rules, and accommodation calculations.'],['SQLite repository','Schema, constraints, migrations, and persistence.']],[42*mm,122*mm]),p('Staff → Windows Forms → Core rules / SQLite repository → local hotel database.'),p('Core entities','H2R'),table([['Entity','Key fields / purpose'],['Room','Number, category, rate, capacity, operational status; Occupied derives from checked-in booking.'],['Guest','Name, phone, email; one guest may have many reservations.'],['Reservation','Guest and room references, dates, status, nights, actual arrival/departure timestamps.'],['StaffAccount','Unique username, display name, salt, and password verifier hash.'],['ReservationRules','Date validity, exclusive-end overlap, blocking status, charge.']],[39*mm,125*mm]),p('Reservation flow','H2R'),p('Enter dates → validate check-out → search eligible rooms → recheck overlap in transaction → save confirmed reservation → calculate accommodation charge.'),p('Integrity and security','H2R'),p('Overlap predicate: existing.CheckIn &lt; requested.CheckOut AND requested.CheckIn &lt; existing.CheckOut. Passwords use PBKDF2-SHA256 with a random salt. SQLite foreign keys, unique room numbers, and date checks protect records. The local database is stored at %LOCALAPPDATA%\\RooseHotel\\roosehotel.db.'),PageBreak()]

st += [p('4. Incremental Implementation','H1R'),table([['Phase','Increment','Completion evidence'],['0','Planning/design','Requirements, feasibility, roles, risks, and design models documented. Fourth category/rate remains an assumption.'],['1','Foundation','SQLite setup, first staff setup/sign-in, dashboard; automated verification/build passed; live UI walkthrough pending.'],['2','Room management','30-room seed, room add/edit/search/status; tests passed.'],['3','Guest management','Register, search, view, edit; tests passed.'],['4','Reservations','Availability, create/edit/cancel, overlap prevention; tests passed.'],['5','Billing','Night count, accommodation summary, print preview; tests passed.'],['6','Check-in/out','Eligibility, timestamps, occupancy, availability release; tests passed.'],['7','Release evidence','Build/test pass. Live acceptance, sign-off, screenshots/video, member numbers remain open.']],[13*mm,38*mm,113*mm]),p('Visual design','H2R'),p('Minimalist white surfaces with fine gold borders/dividers and coffee-brown headings, active states, and primary actions. The swan mark is used as a small brand detail.'),p('Room data assumption','H2R'),p('The overview specifies 30 rooms and four categories; the visual reference shows Standard ₦80,000, Deluxe ₦120,000, Executive Suite ₦180,000. It does not specify the fourth category/rate or room allocation. Family Suite at ₦220,000 is a development assumption to confirm with the group.' ,'NoteR'),p('Operating limits','H2R'),p('This version uses one local database; it is not a networked multi-user service and does not process online payments. Billing is accommodation-only.'),PageBreak()]

st += [p('5. Test Results','H1R'),p('Environment: Windows x64, .NET SDK 9.0.305 / runtime 9.0.9, VSTest 17.14.1. Final automated suite: 12 passed, 0 failed. Full solution build: succeeded, 0 warnings, 0 errors (28 Nov 2026). Full logs are recorded in docs/test-plan.md.'),table([['Test area','Coverage','Result'],['Unit','Date boundaries, overlap, password hash, charge.','Pass'],['Room/guest data','Seed 30 rooms, idempotency, create/update, duplicate; guest create/update/search.','Pass'],['Reservations','Overlap/adjacent dates, update/cancel, room release.','Pass'],['Billing','3 nights × ₦120,000 = ₦360,000.','Pass'],['Check-in/out','Migration, early arrival rejection, timestamps, occupied/unavailable, release.','Pass'],['Staff access','First account, valid/invalid password, duplicate username.','Pass'],['Persistence','Close/reopen repository and verify records.','Pass'],['UI acceptance','Live staff login, complete front-desk flow, group sign-off.','Pending manual walkthrough']],[34*mm,98*mm,32*mm]),p('Test interpretation','H2R'),p('Automated tests exercise Core/Data behavior and SQLite integration. They do not automate Windows Forms UI, visual layout, dialogs, or print output. Complete the real application walkthrough and record its results before final acceptance.','NoteR'),p('Commands','H2R'),p('Build: dotnet build RooseHotel.sln --no-restore --verbosity minimal -p:BaseOutputPath=bin/release/ -p:UseSharedCompilation=false<br/>Tests: dotnet test RooseHotel.Tests/RooseHotel.Tests.csproj --no-restore --no-build --verbosity normal --logger "console;verbosity=normal"'),PageBreak()]

st += [p('6. Staff Guide and Demo Plan','H1R'),p('First use','H2R'),p('Start the app on Windows. On first launch, create the initial staff account using a private password, then sign in. No default credentials are provided. The database is local at %LOCALAPPDATA%\\RooseHotel\\roosehotel.db.'),table([['Task','Staff action'],['Dashboard','Review room counts and today’s arrivals/departures.'],['Rooms / Guests','Search or edit room records; register, search, or update a guest.'],['Availability','Enter stay dates and guest count; search rooms.'],['Reservations','Choose guest and available room; review estimate and confirm.'],['Billing','Select reservation, review nights/rate/total, use print preview.'],['Check-in/out','Find eligible booking, record arrival; later record checkout.']],[43*mm,121*mm]),p('Suggested 5–7 minute demonstration','H2R'),p('1. Show setup or sign in with a presentation account; do not reveal its password. 2. Show dashboard and search rooms. 3. Register a synthetic guest. 4. Search future dates and create a reservation. 5. Attempt an overlapping booking and show rejection. 6. Show 3-night Deluxe charge of ₦360,000. 7. On an eligible date, check in, show Occupied/unavailable, then check out and show released room.'),p('Use fictional guest data and dates around the recording day. A static mockup does not substitute for a running app. Demo video: [ADD SHAREABLE LINK AFTER RECORDING].','NoteR'),p('Screenshots','H2R'),p('No live UI screenshots are included as acceptance evidence. Capture Dashboard, Rooms, Guests, Reservations, Billing, and Check-in/Check-out during the group walkthrough.'),PageBreak()]

st += [p('7. Conclusion and Hand-in Checklist','H1R'),p('The core hotel reservation lifecycle is implemented in six increments and supported by requirements, design models, an execution log, 12 passing automated tests, and a clean full-solution build. The group should confirm the fourth category/rate and review the report.'),table([['Submission item','Current state / action'],['Final single PDF','Prepared: this document.'],['GitHub repository','https://github.com/Build-01/GROUP10_ROOSE'],['Member names and roles','Included from project overview.'],['Matriculation numbers','Add all three numbers on cover before submission.'],['Demo video','Record the live app and add a shareable link.'],['UI screenshots','Capture real app screens during walkthrough.'],['Acceptance sign-off','Run and record group walkthrough.'],['Fourth category/rate','Confirm Family Suite / ₦220,000 and room allocation.']],[48*mm,116*mm]),p('Project records','H2R'),p('Requirements: docs/requirements.md. Design: docs/design.md. Increment log: docs/development-plan.md. Tests: docs/test-plan.md. Staff guide: docs/user-guide.md. Assignment source materials: Group Topics.pdf, Group Project Questions.pdf, and the Group 10 project overview/feasibility study.'),p('The implementation and automated verification are complete. The hand-in is prepared but still needs group-specific details and live acceptance evidence. No member numbers, video URL, screenshots, or sign-off have been invented.','NoteR')]

doc.build(st,onFirstPage=frame,onLaterPages=frame)
print(OUT)
